Section Stage.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMB.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis EXT : HAJ.asan_ext_ok L ar SCFG HI PMB.EXT.
Let LYa := PMB.ly_as0 L C LY.

Theorem grow1 : PMSPA.opnew_spec RSEGS AD L ar HI -> forall (fx : FPState) R M model K LBX FF LK Aw cr ov fb b k stk d sp r pk kd,
    ri_inv HI (PEC.enc_own (PEC.ENC b k stk d) ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA AD L ar R M sp r 0 ->
    getr R (reg 10) = Z_to_bv 64 (ov + 24) -> PMSPA.aobjA FF ov 56 -> ov mod 8 = 0 ->
    PECA.enc_atA RSEGS EE L ar M ov fb (PEC.ENC b k stk d) -> Z.of_nat (length stk) = PEC.ecap k -> 0 < k <= 11 ->
    PMSTA.base_okA RSEGS AD M ->
    getr R (reg 11) = Z_to_bv 64 pk -> pk mod 4 = 0 -> byte_at M (S pk) 0 -> PMBEK.argp (ar_sptop ar) FF sp (ov + 32) pk 4 -> (pk + 4 <= ov \/ ov + 56 <= pk) ->
    L5.u32_at RSEGS M pk kd -> 0 <= kd <= 3 -> acredit_ok L cr (24 * PEC.ecap (k + 1)) ->
    (forall (fx8 : FPState) R8 M8 model8 Aw8 B, PEBEPGS.gmid L ar HI R M model LBX FF LK Aw cr ov b k stk sp pk kd B R8 M8 model8 Aw8 ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx8 R8 0xb0ddc M8 model8) K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R 0xb417c M model) K.
Proof.
